-- Embeddings use the selected model's 1,536 dimensions.
ALTER TABLE chunks
    ALTER COLUMN embedding TYPE vector(1536);

-- Preserve the stable ID generated by the chunker.
-- The existing "id" remains the database row's primary key.
ALTER TABLE chunks
    ADD COLUMN IF NOT EXISTS chunk_id UUID;

-- Preserve block ranges, table row ranges, and chunking metadata.
-- The existing source_locator column will hold the citation URL.
ALTER TABLE chunks
    ADD COLUMN IF NOT EXISTS source_metadata JSONB
    NOT NULL DEFAULT '{}'::jsonb;

-- Chunk positions restart in each section.
ALTER TABLE chunks
    DROP CONSTRAINT IF EXISTS chunks_ingestion_run_id_position_key;

CREATE UNIQUE INDEX IF NOT EXISTS chunks_run_section_position
    ON chunks (ingestion_run_id, section, position);

-- The same exported chunk may appear in different historical runs,
-- but it must not appear twice within one run.
CREATE UNIQUE INDEX IF NOT EXISTS chunks_run_chunk_id
    ON chunks (ingestion_run_id, chunk_id);

-- Record which model produced each run's vectors.
ALTER TABLE ingestion_runs
    ADD COLUMN IF NOT EXISTS embedding_model TEXT;

ALTER TABLE ingestion_runs
    ADD COLUMN IF NOT EXISTS embedding_dimensions INTEGER
    CHECK (embedding_dimensions = 1536);